import json
import os

def validate_outputs():
    # Define expected outputs
    expected_outputs = [
        "outputs/t01_selected_indicators.csv",
        "outputs/t05_clean_stops.csv",
        "outputs/t08_pois_clean.csv",
        "outputs/t10_accessibility_scores.csv",
        "outputs/t13_city_clusters.csv"
    ]

    # Initialize validation summary
    validation_summary = []

    # Check each expected output
    for output in expected_outputs:
        if not os.path.exists(output):
            # Output is missing
            validation_summary.append(
                {
                    "check_name": "Output exists",
                    "passed": False,
                    "message": "Output '{}' is missing".format(output)
                }
            )
        else:
            if os.path.getsize(output) == 0:
                # Output is empty
                validation_summary.append(
                    {
                        "check_name": "Output is not empty",
                        "passed": False,
                        "message": "Output '{}' is empty".format(output)
                    }
                )

    # Write validation summary to JSON file
    with open("outputs/t14_validation_summary.json", "w") as f:
        json.dump(validation_summary, f)

    # Return 0 to indicate successful validation
    return 0

if __name__ == "__main__":
    import sys
    sys.exit(validate_outputs())
